import ollama

def embed(texts: list[str]) -> list[list[float]]:
    out = []
    for t in texts:
        r = ollama.embeddings(model="{{model_name}}", prompt=t)
        out.append(r["embedding"])
    return out

if __name__ == "__main__":
    v = embed(["hello", "world"])
    print(len(v), len(v[0]))
